insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"MARGIN_EQ_3","title":"¿La diferencia final será de exactamente 3?","description":"Se corrige con el marcador final.","category":"diferencia","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_eq","n":3},"priority":0,"cooldown":2,"tags":["diferencia"]},{"code":"MARGIN_EQ_4","title":"¿La diferencia final será de exactamente 4?","description":"Se corrige con el marcador final.","category":"diferencia","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_eq","n":4},"priority":0,"cooldown":2,"tags":["diferencia"]},{"code":"MARGIN_EQ_5","title":"¿La diferencia final será de exactamente 5?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_eq","n":5},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"MARGIN_GTE_2","title":"¿El ganador sacará al menos 2 de ventaja?","description":"Se corrige con el marcador final.","category":"diferencia","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_gte","n":2},"priority":0,"cooldown":2,"tags":["diferencia"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;